#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;
int main() {
    int n; if (cin >> n) {
        unordered_set<int> st;
        for (int i = 0; i < n; i++) { int x; cin >> x; st.insert(x); }
        int best = 0;
        for (int x : st) {
            if (!st.count(x - 1)) {
                int cur = x, streak = 1;
                while (st.count(cur + 1)) { cur++; streak++; }
                best = max(best, streak);
            }
        }
        cout << best << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.HashSet;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            HashSet<Integer> st = new HashSet<>();
            for (int i = 0; i < n; i++) st.add(sc.nextInt());
            int best = 0;
            for (int x : st) {
                if (!st.contains(x - 1)) {
                    int cur = x, streak = 1;
                    while (st.contains(cur + 1)) { cur++; streak++; }
                    best = Math.max(best, streak);
                }
            }
            System.out.println(best);
        }
    }
}

